 const label=v=>names[v]??v??'未知',badge=(text,status='')=>'<span class="tag '+(['failed','error'].includes(status)?'error':['waiting','resource','model_defer'].includes(status)?'wait':'')+'">'+esc(text)+'</span>',button=(text,attrs='')=>'<button '+attrs+'>'+esc(text)+'</button>',empty=text=>'<div class="empty">'+esc(text)+'</div>',notice=text=>'<p class="notice">'+esc(text)+'</p>';
 let disposed=false,abort=null,detailAbort=null,serial=0,returnFocus=null;const state={section:'overview',source:'all',kind:'all',status:'all',offset:0,refKind:null,refId:null,data:null,error:'',loading:false,detail:null,dirty:false,busy:false,draft:null,settingsRevision:null,saveNotice:'',confirmation:null};
 const settingsUI=createActivitySettingsUI({root,state,esc,api,load,render,close});
 function applyRoute(){if(!settingsUI.guard())return;const r=navigation.route??{};state.section=['overview','tasks','choices','resources','settings'].includes(r.section)?r.section:'overview';for(const key of ['source','kind','status'])state[key]=r[key]??'all';state.offset=0;state.refKind=r.refKind??null;state.refId=r.refId??null;close();void load().then(()=>{if(r.id&&r.detailKind)void inspect(r.detailKind,r.id);});}
 async function api(suffix,query,signal,options={}){const r=await fetch('/api/ai-friend-activity'+suffix+'?'+new URLSearchParams(query),{credentials:'same-origin',cache:'no-store',...options,signal});const body=await r.json();if(!r.ok)throw Object.assign(Error(body.error??'读取未完成'),{status:r.status});return body;}
 async function load(){
  abort?.abort();const mine=abort=new AbortController(),request=++serial;state.loading=true;render();
  const query={section:state.section,source:state.source,kind:state.kind,status:state.status,offset:state.offset,limit:24};if(state.refKind&&state.refId){query.refKind=state.refKind;query.refId=state.refId;}
  try{const data=await api('',query,mine.signal);if(disposed||request!==serial)return;state.data=data;settingsUI.receive(data);state.error='';}catch(e){if(!mine.signal.aborted&&!disposed&&request===serial)state.error=e.message;}finally{if(!disposed&&request===serial){state.loading=false;render();}}
 }
 function taskCard(t){return '<article class="card task"><div class="row"><strong>'+esc(t.label)+'</strong>'+badge(t.state.label,t.state.code)+'</div><p class="summary">'+esc(t.summary)+'</p><p>'+esc(t.state.reason)+'</p>'+(t.wake?'<p class="muted">'+esc(t.wake.label)+'：'+esc(t.wake.at?time(t.wake.at):t.wake.kind)+'；届时重新考虑</p>':'')+'<div class="row"><small>'+esc(label(t.source??'unknown'))+' · '+esc(time(t.at))+'</small>'+button('查看过程','data-detail="intent" data-id="'+esc(t.id)+'"')+'</div></article>';}
