 function overview(d){const b=d.overview;if(!b?.available)return empty('当前尚无可读取的统一调度记录。');const latest=b.decisions.find(x=>x.adopted),counts=b.counts??{};return '<div class="grid"><article class="card accent"><span class="eyebrow">当前执行状态</span><h2>'+esc(b.scheduler.current.label)+'</h2><p>'+esc(b.scheduler.current.reason??'以任务实际状态和回执为准。')+'</p>'+(b.scheduler.current.retryAt?'<p>记录的重新考虑时间：'+esc(time(b.scheduler.current.retryAt))+'</p>':'')+'</article><article class="card"><span class="eyebrow">最近一次已提交的模型选择 · 历史记录</span><h2>'+esc(latest?label(latest.action):'暂无记录')+'</h2><p>'+esc(latest?.reason??'没有保存的简短理由。')+'</p><small>'+esc(time(latest?.at))+'</small></article></div><div class="metrics">'+[['等待选择',counts.pending??0],['等待条件',counts.waiting??0],['运行事项',counts.running??0],['暂停事项',counts.paused??0]].map(([k,v])=>'<article class="card"><span>'+esc(k)+'</span><strong>'+v+'</strong></article>').join('')+'</div><div class="row heading"><h2>正在处理与暂停中的事项</h2>'+button('查看全部事项','data-section="tasks"')+'</div>'+(b.current.length?b.current.map(taskCard).join(''):empty('当前没有已记录的执行事项。'))+'<div class="row heading"><h2>等待中的事项</h2>'+button('查看待办','data-section="tasks"')+'</div>'+b.queue.slice(0,6).map(taskCard).join('')+notice('选择开始不等于执行成功；最近选择安静也不代表每条消息都被忽略。当前摘要和最近选择分别读取。');}
 function filters(d){const options=(items,value)=>'<option value="all">全部</option>'+items.map(x=>'<option value="'+esc(x.id??x)+'" '+((x.id??x)===value?'selected':'')+'>'+esc(x.label??label(x))+'</option>').join('');return '<div class="filters"><label>来源<select data-filter="source">'+options(d.catalog.sources,state.source)+'</select></label><label>活动类型<select data-filter="kind">'+options(d.catalog.kinds,state.kind)+'</select></label><label>记录状态<select data-filter="status">'+options(state.section==='choices'?['committed','stale','failed','interrupted','thinking']:d.catalog.statuses,state.status)+'</select></label>'+((state.refKind&&state.refId)?'<div class="reference">仅查看关联任务 '+esc(state.refId)+button('清除关联','data-action="clear-ref"')+'</div>':'')+'</div>';}
 function listing(d){return filters(d)+'<p class="muted">匹配 '+d.paging.total+' 条记录 · 当前第 '+(d.paging.total?state.offset+1:0)+'–'+(state.offset+d.items.length)+' 条</p>'+(d.items.length?d.items.map(state.section==='choices'?choiceCard:taskCard).join(''):empty(state.refId?'没有找到该任务的关联记录；原平台任务仍可在工作台查看。':'当前筛选下没有记录。'))+'<div class="row pager">'+button('上一页','data-action="prev" '+(state.offset===0?'disabled':''))+button('下一页','data-action="next" '+(!d.paging.hasMore?'disabled':''))+'</div>'+notice('筛选和分页查询完整已有记录。全局休息没有单一平台归属，不自动归为B站或QQ选择。');}
 function resources(d){const b=d.overview,r=b?.resources,v=r?.video,a=v?.automatic,m=v?.manual;if(!b)return empty('当前无资源记录。');const cards=[];if(a)cards.push(['B站自动探索',a.explorations+' / '+a.explorationLimit,'进入观看阶段前预留；未必成功完成观看。'],['B站自动活动准入',a.decisions+' / '+a.decisionLimit,'仅计B站自动活动；不是全部全局选择次数。']);if(m)cards.push(['用户要求阅读',m.used+' / '+m.limit,'使用独立任务额度。']);if(r?.workshop){const w=r.workshop;cards.push(['自主工作任务',w.tasksUsed+' / '+w.taskLimit,'独立于B站；包含当天续做的旧任务。'],['自主工作模型步骤',w.stepsUsed+' / '+w.stepLimit,'失败也计数，每个步骤后交回统一选择。'],['自制工具执行',w.scriptUsed+' / '+w.scriptLimit,'试跑和正式运行共享原有额度。']);}if(r?.growth)cards.push(['共享成长与情绪审核',r.growth.used+' / '+r.growth.limit,'剩余 '+r.growth.remaining+' 次']);return '<div class="grid">'+cards.map(([k,n,t])=>'<article class="card"><span class="eyebrow">'+esc(k)+'</span><h2>'+esc(n)+'</h2><p>'+esc(t)+'</p></article>').join('')+'</div>'+notice('额度是上限，不是必须完成的数量。活动中心不会因刷新消耗探索次数。')+'<article class="card"><h2>冷却与连接记录</h2><p>自动活动下一可用时间：'+esc(time(a?.nextAfterCooldown))+'</p><p>手动任务下一可用时间：'+esc(time(m?.nextAfterCooldown))+'</p><p>QQ：'+esc(b.connections.qq?.classification??'暂无连接记录')+' · 账号核验 '+(b.connections.qq?.accountVerified?'已通过':'未确认')+'</p><p>B站：'+(b.connections.bilibili?.bound?'有账号绑定记录':'无绑定记录')+' · 最近收件记录 '+esc(time(b.connections.bilibili?.recordUpdatedAt))+'</p><small>以上是已有记录，打开页面不会重新登录核验或轮询平台。</small></article><article class="card"><h2>模型与执行异常</h2><p>当前跟踪到 '+b.models.active.length+' 个模型调用。</p>'+(b.scheduler.lastError?'<p class="error-text">'+esc(b.scheduler.lastError)+'</p>':'')+(b.models.recentErrors??[]).slice(0,12).map(e=>'<p>'+esc(e.label)+' · '+esc(e.status)+' · '+esc(e.kind??e.errorKind??e.error??'错误详情未记录')+'</p>').join('')+notice(b.models.notice)+'</article>';}
 function render(){if(disposed)return;const scroll=$('.viewport')?.scrollTop??0,d=state.data,valid=d?.schema==='ai-friend/activity-console/1'&&d.section===state.section;$('#ac-app').innerHTML='<main class="viewport"><div class="content"><header class="row"><div><span class="eyebrow">同一角色 · 全局运行视图</span><h1>活动中心</h1><p class="muted">她关注什么、选择什么，以及实际发生了什么。</p></div>'+button(state.loading?'读取中…':'刷新视图','data-action="refresh" '+(state.loading?'disabled':''))+'</header><nav aria-label="活动中心栏目">'+['overview','tasks','choices','resources','settings'].map(s=>button(label(s),'data-section="'+s+'" aria-current="'+(state.section===s?'page':'false')+'"')).join('')+'</nav><p class="updated">'+(d?'读取于 '+esc(time(d.generatedAt)):'正在读取已有记录')+' · 每20秒只读更新</p>'+(state.error?'<div role="alert" class="card error-text">'+esc(state.error)+'；上次数据可能已过时。'+button('重试','data-action="refresh"')+'</div>':'')+(valid&&d.available?(state.section==='overview'?overview(d):state.section==='resources'?resources(d):state.section==='settings'?settingsUI.draw(d):listing(d)):empty(state.loading?'正在读取…':'当前没有可用的活动数据。'))+'<footer>任务、人格与记忆仍由原模块持有；这里展示已有记录与简短选择依据。</footer></div></main>';$('.viewport').scrollTop=scroll;}
