   if(kind==='decision'){const c=d.decision;html=choiceCard(c)+notice(c.notice)+c.updates.map(u=>'<article class="card"><strong>'+esc(u.action==='defer'?'本次暂缓':u.action==='dismiss'?'本次放下':'记录的更新')+'</strong><p>'+esc(u.reason)+'</p>'+(u.id?button('查看对应事项','data-detail="intent" data-id="'+esc(u.id)+'"'):'')+'</article>').join('')+(c.target?.id?button('查看选中事项的实际过程','data-detail="intent" data-id="'+esc(c.target.id)+'"'):'');}
